"""``healthytoon init`` — write a documented starter ``healthytoon.toml``."""

from __future__ import annotations

from pathlib import Path
from typing import Annotated

import typer

from healthytoon.errors import EXIT_OK, EXIT_USAGE

__all__ = ["run"]

_CONFIG_FILENAME = "healthytoon.toml"

_CONFIG_TEMPLATE = """\
# Healthytoon configuration.
# Generated by `healthytoon init`; edit to taste.
# Run `healthytoon list` for check ids and `healthytoon explain <id>` for details.

# Repository-relative globs to scan. "**" means the whole repository.
include = ["**"]

# Paths excluded from the audit. Add project-specific build or vendor dirs here.
exclude = [
    ".git",
    ".hg",
    ".svn",
    ".venv",
    "venv",
    "__pycache__",
    "build",
    "dist",
    "node_modules",
    "*.egg-info",
]

# Minimum severity that fails `healthytoon check`
# (critical | high | medium | low | info | none).
fail_on = "high"

[output]
format = "terminal"
color = "auto"
output = "-"

# Retune a check without disabling it. Uncomment and adjust as needed.
# [rules."maintainability.function_length"]
# enabled = true
# severity = "high"
#
# [rules."ci.actions_pinned"]
# enabled = true
# severity = "high"
"""


def run(
    path: Annotated[Path, typer.Argument(help="target directory")] = Path("."),
    force: Annotated[
        bool,
        typer.Option("--force", help="overwrite an existing healthytoon.toml"),
    ] = False,
) -> int:
    """Create a documented ``healthytoon.toml`` inside ``PATH``."""

    if path.exists() and not path.is_dir():
        typer.echo(f"healthytoon: error: not a directory: {path}", err=True)
        return EXIT_USAGE

    target = path / _CONFIG_FILENAME
    if target.exists() and not force:
        typer.echo(
            f"healthytoon: error: {target} already exists (use --force to overwrite)",
            err=True,
        )
        return EXIT_USAGE

    path.mkdir(parents=True, exist_ok=True)
    target.write_text(_CONFIG_TEMPLATE, encoding="utf-8")
    typer.echo(f"Created {target}")
    return EXIT_OK
